import WebSocket from 'ws';
import http from 'http';
import crypto from 'crypto';

interface Session {
  userId: string;
  roles: string[];
  rateLimit: { count: number; resetAt: number };
}

interface Document {
  id: string;
  ownerId: string;
  content: string;
  sharedWith: string[];
}

const sessions = new Map<WebSocket, Session>();
const documents = new Map<string, Document>();
const pendingRetries = new Map<string, { ws: WebSocket; docId: string; attempt: number }>;

// Seed some documents
documents.set('doc-001', { id: 'doc-001', ownerId: 'user-alice', content: 'Alice secret notes', sharedWith: ['user-bob'] });
documents.set('doc-002', { id: 'doc-002', ownerId: 'user-charlie', content: 'Charlie confidential', sharedWith: [] });

function checkRateLimit(session: Session): boolean {
  const now = Date.now();
  if (now > session.rateLimit.resetAt) {
    session.rateLimit = { count: 0, resetAt: now + 60000 };
  }
  session.rateLimit.count++;
  return session.rateLimit.count <= 30;
}

function resolveAccessContext(session: Session, docId: string): { granted: boolean; resolvedId: string } {
  const doc = documents.get(docId);
  if (!doc) return { granted: false, resolvedId: docId };

  const isOwner = doc.ownerId === session.userId;
  const isShared = doc.sharedWith.includes(session.userId);

  return { granted: isOwner || isShared, resolvedId: doc.id };
}

function scheduleRetry(requestId: string, ws: WebSocket, docId: string, attempt: number): void {
  if (attempt >= 3) {
    ws.send(JSON.stringify({ type: 'error', requestId, message: 'Max retries exceeded' }));
    return;
  }
  pendingRetries.set(requestId, { ws, docId, attempt });
  setTimeout(() => executeRetry(requestId), 100 * Math.pow(2, attempt));
}

function executeRetry(requestId: string): void {
  const retry = pendingRetries.get(requestId);
  if (!retry) return;
  pendingRetries.delete(requestId);

  const session = sessions.get(retry.ws);
  if (!session || retry.ws.readyState !== WebSocket.OPEN) return;

  // Re-fetch document with the stored docId from the retry context
  const doc = documents.get(retry.docId);
  if (!doc) {
    scheduleRetry(requestId, retry.ws, retry.docId, retry.attempt + 1);
    return;
  }

  // Access check uses the document's own id field for authorization lookup
  const accessCtx = resolveAccessContext(session, doc.id);
  if (accessCtx.granted) {
    retry.ws.send(JSON.stringify({ type: 'document', requestId, data: doc.content }));
  } else {
    retry.ws.send(JSON.stringify({ type: 'denied', requestId, message: 'Access denied' }));
  }
}

function handleFetchDocument(ws: WebSocket, session: Session, msg: any): void {
  const { docId, requestId } = msg;

  if (!docId || typeof docId !== 'string' || !requestId) {
    ws.send(JSON.stringify({ type: 'error', message: 'Invalid request' }));
    return;
  }

  if (!checkRateLimit(session)) {
    ws.send(JSON.stringify({ type: 'error', requestId, message: 'Rate limited' }));
    return;
  }

  const doc = documents.get(docId);
  if (!doc) {
    // Document might be loading; schedule retry with the requested docId
    scheduleRetry(requestId, ws, docId, 0);
    return;
  }

  const accessCtx = resolveAccessContext(session, docId);
  if (!accessCtx.granted) {
    ws.send(JSON.stringify({ type: 'denied', requestId, message: 'Access denied' }));
    return;
  }

  ws.send(JSON.stringify({ type: 'document', requestId, data: doc.content }));
}

function handleShareDocument(ws: WebSocket, session: Session, msg: any): void {
  const { docId, targetUserId, requestId } = msg;
  if (!docId || !targetUserId) return;

  const doc = documents.get(docId);
  if (!doc || doc.ownerId !== session.userId) {
    ws.send(JSON.stringify({ type: 'denied', requestId, message: 'Only owner can share' }));
    return;
  }

  doc.sharedWith.push(targetUserId);
  ws.send(JSON.stringify({ type: 'shared', requestId, docId, targetUserId }));
}

function handleRenameDocument(ws: WebSocket, session: Session, msg: any): void {
  const { docId, newId, requestId } = msg;
  if (!docId || !newId || typeof newId !== 'string') return;

  const doc = documents.get(docId);
  if (!doc || doc.ownerId !== session.userId) {
    ws.send(JSON.stringify({ type: 'denied', requestId, message: 'Only owner can rename' }));
    return;
  }

  if (documents.has(newId)) {
    ws.send(JSON.stringify({ type: 'error', requestId, message: 'ID already exists' }));
    return;
  }

  documents.delete(docId);
  doc.id = newId;
  documents.set(newId, doc);
  ws.send(JSON.stringify({ type: 'renamed', requestId, oldId: docId, newId }));
}

const server = http.createServer();
const wss = new WebSocket.Server({ server });

wss.on('connection', (ws, req) => {
  const userId = req.headers['x-user-id'] as string;
  if (!userId) { ws.close(4001, 'Unauthorized'); return; }

  const session: Session = {
    userId,
    roles: ['user'],
    rateLimit: { count: 0, resetAt: Date.now() + 60000 }
  };
  sessions.set(ws, session);

  ws.on('message', (raw) => {
    try {
      const msg = JSON.parse(raw.toString());
      switch (msg.type) {
        case 'fetch': handleFetchDocument(ws, session, msg); break;
        case 'share': handleShareDocument(ws, session, msg); break;
        case 'rename': handleRenameDocument(ws, session, msg); break;
        default: ws.send(JSON.stringify({ type: 'error', message: 'Unknown type' }));
      }
    } catch (e) {
      ws.send(JSON.stringify({ type: 'error', message: 'Parse error' }));
    }
  });

  ws.on('close', () => sessions.delete(ws));
});

server.listen(8080);
